# frozen_string_literal: true

# Generated by `rails g ruflet:install` (Ruflet::Rails::InstallSupport.default_initializer),
# then customised the way the docs describe: services, extensions and colors.
Ruflet::Rails.configure do |config|
  config.app_name = "Rails App"
  config.backend_url = ENV.fetch("RUFLET_BACKEND_URL", "http://localhost:3000")

  config.services = %w[camera]
  config.extensions = %w[webview]

  # Build assets. Replace these with your app artwork when ready.
  config.splash_screen = Rails.root.join("app/assets/images/splash.png")
  config.icon_launcher = Rails.root.join("app/assets/images/icon.png")

  config.splash_color = "#101820"
  config.icon_background = "#FFFFFF"
end
